const failed = [];
$input.all().forEach((r, i) => {
  const o = orders[i].json, e = r.json.error;
  if (!e) return;
  // already confirmed (e.g. by the team at the same time) -> not a failure
  if (/not in a state requiring confirmation/i.test(String(e.data?.message || e.message || ''))) return;
  const why = [e.data?.name, e.data?.message || e.message].filter(Boolean).join(': ');
  const cur = String(o.note || '');
  if (/confirm failed/i.test(cur.replace(/<[^>]+>/g, ' '))) return;   // remark only once
  failed.push({ json: { order_id: o.order_id, order_name: o.order_name, error: why, note: cur + '<p>Confirm Failed - Odoo error: ' + why + '</p>' } });
});
return failed;
